    "latex": "x^{4} + x^{2} - 2=0",
    "answerLatex": "S=\\{-1,1\\}",
    "solution": {
      "steps": [
        "Hacemos \\(t=x^2\\) y resolvemos \\(t^{2} + t - 2\\)=0.",
        "Los valores son \\(t=1\\) y \\(t=-2\\).",
        "El valor negativo de \\(t\\) no puede ser \\(x^2\\) para \\(x\\in\\mathbb{R}\\).",
        "De \\(x^2=1\\) resulta \\(x=\\pm 1\\)."
      ]
    },
