        "Asíntota vertical \\(x=-2\\) y horizontal \\(y=-1\\). El recorrido excluye \\(-1\\).",
        "Corte con X: \\((1,0)\\). Corte con Y: \\((0,\\frac{1}{2})\\).",
        "Es estrictamente decreciente en cada intervalo de su dominio porque, al aumentar x sin cruzar -2, el cociente 3/(x−(-2)) disminuye. No tiene extremos.",
