    "prompt": "Representa la función. Indica dominio, recorrido, cortes, asíntotas, monotonía y centro de simetría.",
    "latex": "f(x)=-1 + \\frac{4}{x - 3}",
    "answerLatex": "D=\\mathbb{R}\\setminus\\{3\\};\\;R=\\mathbb{R}\\setminus\\{-1\\}",
    "solution": {
      "steps": [
        "El denominador se anula en \\(x=3\\). Dominio: \\(\\mathbb{R}\\setminus\\{3\\}\\).",
        "Asíntota vertical \\(x=3\\) y horizontal \\(y=-1\\). El recorrido excluye \\(-1\\).",
        "Corte con X: \\((7,0)\\). Corte con Y: \\((0,- \\frac{7}{3})\\).",
        "Es estrictamente decreciente en cada intervalo de su dominio porque, al aumentar x sin cruzar 3, el cociente 4/(x−(3)) disminuye. No tiene extremos.",
        "Es una hipérbola trasladada con centro de simetría \\((3,-1)\\). La gráfica muestra sus dos ramas."
      ]
    },
