        "Paramétricas: \\(\\begin{cases}x=0+3t\\\\y=2+(-4)t\\end{cases}\\).",
        "Continua: \\(\\frac{x-(0)}{3}=\\frac{y-(2)}{-4}\\).",
        "Punto–pendiente: \\(y-(2)=- \\frac{4}{3}(x-(0))\\).",
